const fin = $('Safety Guardrails').first().json;
const updates = [];
const nowIso = $now.toISO();
if (fin.needs_watering_final && !fin.tank_empty && !fin.dry_run_mode) {
updates.push({ key: 'last_watered_utc', value: nowIso, LastUpdated: nowIso });
}
const newConf = Number(fin.species_confidence ?? 0);
const storedConf = Number(fin.species_stored_confidence ?? 0);
if (newConf > storedConf) {
updates.push({ key: 'last_species_guess', value: fin.species_guess, LastUpdated: nowIso });
updates.push({ key: 'species_confidence', value: String(newConf), LastUpdated: nowIso });
}
if (fin.temperature_tolerance_c !== undefined && fin.temperature_tolerance_c !== null) {
updates.push({ key: 'current_temp_tolerance_c', value: String(fin.temperature_tolerance_c), LastUpdated: nowIso });
}
return updates.map((u) => ({ json: u }));

const vision = $('Normalize Vision Output').first().json;
const judge = $('Normalize Judge Output').first().json;
const yolo = $('Build YOLO Opinion').first().json;
const upload = $('Upload Scan Photo').first().json;
const item = $input.first().json;
const timestamp = judge.scan_timestamp;
const aiNotes = item.ai_notes ?? '';
return [{ json: {
timestamp,
drive_links: upload.id ? 'https://drive.google.com/file/d/' + upload.id + '/view' : '',
vision_opinion: JSON.stringify({ framing_quality: vision.framing_quality, symptoms_observed: vision.symptoms_observed, suspected_issues: vision.suspected_issues, confidence: vision.confidence, affected_areas: vision.affected_areas }),
yolo_opinion: JSON.stringify(yolo),
judge_verdict: judge.verdict,
judge_reasoning: judge.reasoning,
treatment_plan: item.treatment_plan ?? '',
user_verdict: '',
treatment_outcome: '',
ai_notes: aiNotes,
} }];

const norm = $('Normalize Photo Output').first().json;
const updates = [];
const nowIso = $now.toISO();
const newConf = Number(norm.species_confidence ?? 0);
const storedConf = Number(norm.species_confidence_stored ?? 0);
if (newConf > storedConf) {
updates.push({ key: 'last_species_guess', value: norm.species_guess, LastUpdated: nowIso });
updates.push({ key: 'species_confidence', value: String(newConf), LastUpdated: nowIso });
}
return updates.map((u) => ({ json: u }));

const snapshot = $('Normalize Sensor Payload').first().json;
const configRows = $('Read SystemConfig').all().map((i) => i.json);
const eventRows = $('Read Event History').all().map((i) => i.json);
const historyNotesRows = $('Read AgentNotes History').all().map((i) => i.json);
const historyNotesText = historyNotesRows.length ? historyNotesRows.map((n) => '- ' + n.note + ' (context: ' + (n.context_ref || '-') + ')').join('\n') : 'none';
const cfg = {};
for (const row of configRows) {
if (row.Key !== undefined && row.Key !== null && String(row.Key).trim() !== '') {
cfg[String(row.Key).trim()] = row.Value;
}
}
const now = Date.now();
const HOUR_MS = 3600000;
const DAY_MS = 86400000;
const lastWatered = cfg['last_watered_utc'] || '';
let hoursSinceWatering = null;
if (lastWatered) {
const t = Date.parse(lastWatered);
if (!isNaN(t)) {
hoursSinceWatering = Math.round(((now - t) / HOUR_MS) * 10) / 10;
}
}
const lastAlert = cfg['last_tank_empty_alert_sent'] || '';
let alertAllowed = true;
if (lastAlert) {
const t = Date.parse(lastAlert);
if (!isNaN(t) && now - t < 12 * HOUR_MS * 1000) {
alertAllowed = false;
}
}
const dryRun = String(cfg['dry_run_mode'] || 'false').toLowerCase() === 'true';
const minRewaterIntervalHours = Number(cfg['min_rewater_interval_hours'] ?? 6);
const isWatered = (r) => r.WateringTriggered === true || r.WateringTriggered === 'TRUE' || r.WateringTriggered === 1 || r.WateringTriggered === 'true';
let wateringCount7d = 0;
let wateringCount30d = 0;
for (const r of eventRows) {
if (!isWatered(r)) { continue; }
const ts = Date.parse(r.Timestamp);
if (isNaN(ts)) { continue; }
if (now - ts <= 7 * DAY_MS) { wateringCount7d += 1; }
if (now - ts <= 30 * DAY_MS) { wateringCount30d += 1; }
}
const toNum = (v) => {
const n = Number(v);
return isNaN(n) ? null : n;
};
const recent = eventRows.slice(-10);
const moistVals = recent.map((r) => toNum(r.MoisturePercent)).filter((v) => v !== null);
const weightVals = recent.map((r) => toNum(r.WeightGrams)).filter((v) => v !== null);
const trendOf = (vals) => {
if (vals.length < 2) {
return { direction: 'stable', delta: null, first: vals[0] ?? null, last: vals[vals.length - 1] ?? null, count: vals.length };
}
const first = vals[0];
const last = vals[vals.length - 1];
const delta = Math.round((last - first) * 10) / 10;
const direction = Math.abs(delta) < 0.5 ? 'stable' : (delta > 0 ? 'rising' : 'falling');
return { direction, delta, first, last, count: vals.length };
};
const moistureTrend = trendOf(moistVals);
const weightTrend = trendOf(weightVals);
let lastWateringEffect = null;
let foundWateredIdx = -1;
for (let i = eventRows.length - 1; i >= 0; i -= 1) {
if (isWatered(eventRows[i])) { foundWateredIdx = i; break; }
}
if (foundWateredIdx >= 0) {
const before = eventRows[foundWateredIdx - 1];
const after = eventRows[foundWateredIdx + 1];
const mBefore = before ? toNum(before.MoisturePercent) : null;
const mAfter = after ? toNum(after.MoisturePercent) : null;
if (mBefore !== null && mAfter !== null) {
lastWateringEffect = Math.round((mAfter - mBefore) * 10) / 10;
}
}
const sanityFlags = [];
const mP = toNum(snapshot.moisture_percent);
if (mP !== null && (mP < 0 || mP > 100)) { sanityFlags.push('moisture_percent out of range 0-100: ' + mP); }
const wG = toNum(snapshot.weight_grams);
if (wG !== null && (wG < 0 || wG > 5000)) { sanityFlags.push('weight_grams out of range 0-5000: ' + wG); }
const aT = toNum(snapshot.air_temp_c);
if (aT !== null && (aT < -10 || aT > 60)) { sanityFlags.push('air_temp_c out of range -10..60: ' + aT); }
const sT = toNum(snapshot.soil_temp_c);
if (sT !== null && (sT < -10 || sT > 60)) { sanityFlags.push('soil_temp_c out of range -10..60: ' + sT); }
const wT = toNum(snapshot.water_temp_c);
if (wT !== null && (wT < 0 || wT > 99)) { sanityFlags.push('water_temp_c out of range 0..99: ' + wT); }
const lL = toNum(snapshot.light_level);
if (lL !== null && lL < 0) { sanityFlags.push('light_level negative: ' + lL); }
const speciesGuess = cfg['last_species_guess'] || 'unknown';
const speciesConfidence = cfg['species_confidence'] || '0';
const prevTolerance = cfg['current_temp_tolerance_c'] || 'none';
const historyCompact = recent.map((r) => ({
timestamp: r.Timestamp,
event_type: r.EventType,
moisture_percent: r.MoisturePercent,
weight_grams: r.WeightGrams,
soil_temp_c: r.SoilTempC,
water_temp_c: r.WaterTempC,
watered: isWatered(r),
water_duration_seconds: r.WaterDurationSeconds,
heater_used: r.HeaterUsed,
species_guess: r.SpeciesGuess,
anomaly_detected: r.AnomalyDetected,
}));
const trendText = (t, unit) => t.delta === null ? 'unknown (fewer than 2 readings)' : t.direction + ' by ' + t.delta + ' ' + unit + ' (' + t.first + ' -> ' + t.last + ', over ' + t.count + ' recent readings)';
const decisionPartsSnapshot = [
'LIVE SENSOR SNAPSHOT (informational only - never decide on this alone):',
'  moisture_percent=' + snapshot.moisture_percent + ', weight_grams=' + snapshot.weight_grams + ', air_temp_c=' + snapshot.air_temp_c + ', air_humidity_percent=' + snapshot.air_humidity_percent + ', soil_temp_c=' + snapshot.soil_temp_c + ', water_temp_c=' + snapshot.water_temp_c + ', light_level=' + snapshot.light_level + ', tank_empty=' + snapshot.tank_empty,
'SENSOR SANITY FLAGS: ' + (sanityFlags.length ? sanityFlags.join('; ') : 'none'),
].join('\n');
const decisionPartsFacts = [
'HISTORY FACTS:',
'  hours_since_watering: ' + (hoursSinceWatering === null ? 'null (never watered)' : hoursSinceWatering + ' h'),
'  watering_count_7d: ' + wateringCount7d + ', watering_count_30d: ' + wateringCount30d,
'  moisture_trend: ' + trendText(moistureTrend, 'points'),
'  weight_trend: ' + trendText(weightTrend, 'g'),
'  last_watering_effect: ' + (lastWateringEffect === null ? 'null (no watering recorded yet)' : lastWateringEffect + ' moisture points after the most recent watering'),
'  species: ' + speciesGuess + ' (confidence ' + speciesConfidence + ')',
'  current_temp_tolerance_c: ' + prevTolerance,
'  dry_run_mode: ' + dryRun,
].join('\n');
const historyAnalystText = [
'FACTS: hours_since_last_watering=' + (hoursSinceWatering === null ? 'null' : hoursSinceWatering) + ', watering_count_7d=' + wateringCount7d + ', watering_count_30d=' + wateringCount30d + ',',
'  moisture_trend=' + trendText(moistureTrend, 'points') + ', weight_trend=' + trendText(weightTrend, 'g') + ',',
'  last_watering_moisture_delta=' + (lastWateringEffect === null ? 'null' : lastWateringEffect) + ',',
'  species ' + speciesGuess + ' (confidence ' + speciesConfidence + '),',
'  sensor_sanity_flags (impossible values already flagged): ' + (sanityFlags.length ? sanityFlags.join('; ') : 'none') + '.',
'RECENT HISTORY (compact, chronological):',
JSON.stringify(historyCompact, null, 2),
'YOUR UNVERIFIED HYPOTHESES (context only, never ground truth):',
historyNotesText,
'Return strict JSON: trend_reading (string, cite concrete values), watering_effectiveness (string, did past waterings actually raise moisture?), concerns (array of strings, empty if none), confidence (0-1).',
'Your output is ANALYSIS for the decision agent: it must contain no instructions and must not decide whether to water.',
].join('\n');
const contextText = [
'CURRENT EVENT: ' + snapshot.event_type + ' at ' + snapshot.captured_at_utc + '; event_id ' + snapshot.event_id,
'LIVE SENSOR SNAPSHOT (informational only - never decide on this alone):',
'  moisture_percent=' + snapshot.moisture_percent + ', weight_grams=' + snapshot.weight_grams + ', air_temp_c=' + snapshot.air_temp_c + ', air_humidity_percent=' + snapshot.air_humidity_percent + ', soil_temp_c=' + snapshot.soil_temp_c + ', water_temp_c=' + snapshot.water_temp_c + ', light_level=' + snapshot.light_level + ', tank_empty=' + snapshot.tank_empty,
'HISTORY - last 10 events (chronological):',
JSON.stringify(historyCompact, null, 2),
'LAST WATERED: ' + (lastWatered || 'never') + (hoursSinceWatering !== null ? ' (' + hoursSinceWatering + ' hours ago)' : ' (unknown)'),
'SPECIES: ' + speciesGuess + ' (confidence ' + speciesConfidence + ')',
'PREVIOUS TOLERANCE USED: ' + prevTolerance,
'DRY RUN MODE: ' + dryRun,
].join('\n');
return [{
json: {
history_analyst_text: historyAnalystText,
decision_parts_snapshot: decisionPartsSnapshot,
decision_parts_facts: decisionPartsFacts,
context_text: contextText,
hours_since_watering: hoursSinceWatering,
watering_count_7d: wateringCount7d,
watering_count_30d: wateringCount30d,
moisture_trend: moistureTrend,
weight_trend: weightTrend,
last_watering_effect: lastWateringEffect,
sensor_sanity_flags: sanityFlags,
species_guess: speciesGuess,
species_confidence: speciesConfidence,
current_temp_tolerance_c: prevTolerance,
dry_run_mode: dryRun,
min_rewater_interval_hours: minRewaterIntervalHours,
tank_empty: snapshot.tank_empty,
last_tank_empty_alert_sent: lastAlert,
alert_allowed: alertAllowed,
event_id: snapshot.event_id,
event_type: snapshot.event_type,
captured_at_utc: snapshot.captured_at_utc,
moisture_percent: snapshot.moisture_percent,
weight_grams: snapshot.weight_grams,
air_temp_c: snapshot.air_temp_c,
air_humidity_percent: snapshot.air_humidity_percent,
soil_temp_c: snapshot.soil_temp_c,
water_temp_c: snapshot.water_temp_c,
light_level: snapshot.light_level,
last_watered_utc: lastWatered,
},
}];

const notes = $('Normalize History Output').first().json.agent_notes ?? [];
const ctx = $('Build Context').first().json.event_id;
const list = Array.isArray(notes) ? notes.slice(0, 3) : [];
return list.map((n) => ({ json: { timestamp: $now.toISO(), agent: 'History Analyst', note: String(n), context_ref: ctx || '', status: 'active' } }));

const dec = $('Normalize Decision Output').first().json;
const ctx = $('Build Context').first().json;
const minIntervalH = Number(ctx.min_rewater_interval_hours ?? 6);
const maxPumpSeconds = 60;
const maxHeaterSeconds = 600;
const maxWaterTempC = 30;
const highConfidenceFloor = 0.8;
const tankEmpty = dec.tank_empty === true;
const dryRun = dec.dry_run_mode === true;
let needsWatering = dec.needs_watering === true;
let duration = Number(dec.water_duration_seconds ?? 0);
let heater = dec.heater_on === true;
let blockedRewater = false;
let intervalNote = '';
if (tankEmpty) { needsWatering = false; duration = 0; heater = false; }
const hoursSince = ctx.hours_since_watering;
const confidence = Number(dec.decision_confidence ?? 0);
const reasoning = String(dec.reasoning_summary || '');
const citesPreviousWatering = /previous.{0,40}(watering|water)/i.test(reasoning) || /last.{0,40}(watering|water)/i.test(reasoning);
if (minIntervalH > 0 && hoursSince !== null && hoursSince < minIntervalH && needsWatering) {
if (confidence >= highConfidenceFloor && citesPreviousWatering) {
intervalNote = ' within_rewater_interval=' + minIntervalH + 'h but exception granted (confidence=' + confidence + ', cites previous watering)';
} else {
needsWatering = false; duration = 0; heater = false; blockedRewater = true;
intervalNote = ' blocked by min_rewater_interval_hours=' + minIntervalH + ' (hours_since=' + hoursSince + ', confidence=' + confidence + ', cites_previous=' + citesPreviousWatering + ')';
}
}
if (duration > maxPumpSeconds) { duration = maxPumpSeconds; }
if (heater && Number(dec.water_temp_c ?? 0) >= maxWaterTempC) { heater = false; }
if (dryRun) { duration = 0; heater = false; }
if (!needsWatering) { duration = 0; heater = false; }
const notes = [tankEmpty ? 'tank_empty override' : '', blockedRewater ? 'rewater blocked' : '', intervalNote, duration >= maxPumpSeconds && !dryRun ? 'pump capped at ' + maxPumpSeconds + 's' : ''].filter(Boolean).join('; ');
return [{ json: Object.assign({}, dec, {
needs_watering_final: needsWatering,
water_duration_final: duration,
heater_final: heater,
blocked_rewater: blockedRewater,
guardrail_notes: notes,
}) }];

const notes = $('Normalize Decision Output').first().json.agent_notes ?? [];
const ctx = $('Build Context').first().json.event_id;
const list = Array.isArray(notes) ? notes.slice(0, 3) : [];
return list.map((n) => ({ json: { timestamp: $now.toISO(), agent: 'Decision Agent', note: String(n), context_ref: ctx || '', status: 'active' } }));

const webhookItem = $('Daily Photo Webhook').first();
const body = webhookItem.json.body || {};
const configRows = $('Read SystemConfig B').all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
const eventRows = $('Read Event History B').all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
const matchRows = $('Read Matching Event Row').all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
const cfg = {};
for (const row of configRows) {
if (row.Key !== undefined && row.Key !== null && String(row.Key).trim() !== '') {
cfg[String(row.Key).trim()] = row.Value;
}
}
const lastWatered = cfg['last_watered_utc'] || '';
let elapsedHours = null;
if (lastWatered) {
const t = Date.parse(lastWatered);
if (!isNaN(t)) {
elapsedHours = Math.round(((Date.now() - t) / 3600000) * 10) / 10;
}
}
const speciesGuess = cfg['last_species_guess'] || 'unknown';
const speciesConfidence = cfg['species_confidence'] || '0';
const dryRun = String(cfg['dry_run_mode'] || 'false').toLowerCase() === 'true';
const eventId = body.event_id || '';
const todayRow = matchRows[0] || null;
const hasSensorRow = todayRow !== null;
const historyCompact = eventRows.slice(-10).map((r) => ({
timestamp: r.Timestamp,
event_type: r.EventType,
moisture_percent: r.MoisturePercent,
weight_grams: r.WeightGrams,
soil_temp_c: r.SoilTempC,
water_temp_c: r.WaterTempC,
watered: r.WateringTriggered,
water_duration_seconds: r.WaterDurationSeconds,
heater_used: r.HeaterUsed,
species_guess: r.SpeciesGuess,
anomaly_detected: r.AnomalyDetected,
}));
const lines = [
"PHOTO: today's quick-check image of the plant.",
"SAME EVENT'S SENSOR DATA (event_id " + eventId + '): ' + (hasSensorRow ? JSON.stringify(todayRow) : '{}'),
'HISTORY - last 10 events (compact):',
JSON.stringify(historyCompact),
'LAST WATERED: ' + (lastWatered || 'never') + (elapsedHours !== null ? ' (' + elapsedHours + ' h ago)' : ''),
'SPECIES ON RECORD: ' + speciesGuess + ' (confidence ' + speciesConfidence + ')',
];
if (hasSensorRow) {
lines.push("TODAY'S DECISION (for your review): see the matching event row above (WateringTriggered, WaterDurationSeconds).");
} else {
lines.push('CONTEXT NOTE: no sensor row for this event_id (WROOM may not have posted yet)');
}
lines.push('Return strict JSON: species_guess, species_confidence (0-1), anomaly_detected (bool), anomaly_description (string|null), watering_review (string: agree/disagree + one-sentence reason), ai_notes (string).');
return [{
json: {
context_text: lines.join('\n'),
event_id: eventId,
event_type: body.event_type || (todayRow && todayRow.EventType) || '',
captured_at_utc: body.captured_at_utc || (todayRow && todayRow.Timestamp) || '',
species_confidence_stored: speciesConfidence,
drive_daily_photos_folder_id: cfg['drive_daily_photos_folder_id'] || '',
battery_percent: body.battery_percent ?? null,
dry_run_mode: dryRun,
today_row: todayRow,
},
binary: webhookItem.binary,
}];

const ctx = $('Build Multimodal Context').first().json;
const b = ctx.battery_percent;
if (b === undefined || b === null || b === '' || isNaN(Number(b))) { return []; }
return [{ json: { key: 'camera_battery_percent', value: String(b), LastUpdated: $now.toISO() } }];

const norm = $('Normalize Photo Output').first().json;
const driveOut = $('Upload Daily Photo').first().json;
const ctx = $('Build Multimodal Context').first().json;
const existingRow = ctx.today_row || {};
return [{
json: {
EventID: norm.event_id,
PhotoFileID: driveOut.id || '',
SpeciesGuess: norm.species_guess,
SpeciesConfidence: norm.species_confidence,
AnomalyDetected: norm.anomaly_detected,
AnomalyDescription: norm.anomaly_description || '',
AI_Notes: existingRow.AI_Notes ? existingRow.AI_Notes : norm.ai_notes,
anomaly_detected: norm.anomaly_detected,
dry_run_mode: norm.dry_run_mode,
ai_notes_text: norm.ai_notes,
watering_review: norm.watering_review,
species_guess: norm.species_guess,
species_confidence: norm.species_confidence,
species_confidence_stored: norm.species_confidence_stored,
},
}];

const webhookItem = $('Scan Photo Webhook').first();
const body = webhookItem.json.body || {};
const rows = $('Read SystemConfig D3').all().map((i) => i.json);
const cfg = {};
for (const row of rows) {
if (row.Key !== undefined && row.Key !== null && String(row.Key).trim() !== '') { cfg[String(row.Key).trim()] = row.Value; }
}
const sessionActive = String(cfg['scan_session_active'] || 'false').toLowerCase() === 'true';
const batteryRaw = cfg['camera_battery_percent'];
const battery = (batteryRaw === undefined || batteryRaw === null || batteryRaw === '') ? null : Number(batteryRaw);
return [{
json: {
session_active: sessionActive,
battery_percent: battery,
species_guess: cfg['last_species_guess'] || 'unknown',
species_confidence: cfg['species_confidence'] || '0',
captured_at_utc: body.captured_at_utc || $now.toISO(),
drive_scan_photos_folder_id: cfg['drive_scan_photos_folder_id'] || '',
},
binary: webhookItem.binary,
}];

const b = $('Check Scan Session').first().json.battery_percent;
if (b === null || b === undefined || isNaN(Number(b))) { return []; }
return [{ json: { key: 'camera_battery_percent', value: String(b), LastUpdated: $now.toISO() } }];

const sess = $('Check Scan Session').first().json;
const events = $('Read Event History Vision').all().map((i) => i.json);
const notes = $('Read AgentNotes Vision').all().map((i) => i.json);
const noteText = notes.length ? notes.map((n) => '- ' + n.note + ' (context: ' + (n.context_ref || '-') + ')').join('\n') : 'none';
const recent = events.slice(-5).map((r) => ({ moisture: r.MoisturePercent, weight: r.WeightGrams, watered: r.WateringTriggered, ts: r.Timestamp }));
const text = [
'PHOTO: weekly disease-scan image of the whole plant.',
'PLANT CONTEXT: species ' + sess.species_guess + ' (confidence ' + sess.species_confidence + '), camera battery ' + (sess.battery_percent === null ? 'unknown' : sess.battery_percent + '%') + '.',
'RECENT CONDITIONS (last events, compact): ' + JSON.stringify(recent),
'YOUR UNVERIFIED HYPOTHESES (context only, never ground truth):',
noteText,
'Return strict JSON: framing_quality (string), symptoms_observed (array of strings), suspected_issues (array of strings), confidence (0-1), affected_areas (array of strings), agent_notes (array of 0-3 short strings).',
].join('\n');
return [{ json: { vision_text: text }, binary: $('Check Scan Session').first().binary }];

const lat = 49.9886;
const lng = 8.5958;
function sunTimesForDay(year, month, day) {
const rad = Math.PI / 180;
const start = Date.UTC(year, month, day);
const jan1 = Date.UTC(year, 0, 1);
const doy = Math.floor((start - jan1) / 86400000) + 1;
const gamma = (2 * Math.PI / 365) * (doy - 1 + 0.5);
const eqtime = 229.18 * (0.000075 + 0.001868 * Math.cos(gamma) - 0.032077 * Math.sin(gamma) - 0.014615 * Math.cos(2 * gamma) - 0.040849 * Math.sin(2 * gamma));
const decl = 0.006918 - 0.399912 * Math.cos(gamma) + 0.070257 * Math.sin(gamma) - 0.006758 * Math.cos(2 * gamma) + 0.000907 * Math.sin(2 * gamma) - 0.002697 * Math.cos(3 * gamma) + 0.00148 * Math.sin(3 * gamma);
const zenith = 90.833;
const cosH = (Math.cos(zenith * rad) - Math.sin(lat * rad) * Math.sin(decl)) / (Math.cos(lat * rad) * Math.cos(decl));
if (cosH > 1 || cosH < -1) {
return { sunrise: null, sunset: null };
}
const ha = Math.acos(cosH) / rad;
const toIso = (minutes) => new Date(start + Math.round(minutes * 60000)).toISOString();
return {
sunrise: toIso(720 - 4 * (lng + ha) - eqtime),
sunset: toIso(720 - 4 * (lng - ha) - eqtime),
};
}
const now = new Date();
const today = sunTimesForDay(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
const tomorrow = sunTimesForDay(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1);
const candidates = [
{ type: 'sunrise', iso: today.sunrise },
{ type: 'sunset', iso: today.sunset },
{ type: 'sunrise', iso: tomorrow.sunrise },
{ type: 'sunset', iso: tomorrow.sunset },
].filter((c) => c.iso && Date.parse(c.iso) > now.getTime());
const nextSunrise = candidates.find((c) => c.type === 'sunrise');
const nextSunset = candidates.find((c) => c.type === 'sunset');
return [{ json: { next_sunrise_utc: nextSunrise ? nextSunrise.iso : '', next_sunset_utc: nextSunset ? nextSunset.iso : '' } }];

const calc = $('Sunrise Sunset Calc').first().json;
const nowIso = $now.toISO();
const updates = [];
if (calc.next_sunrise_utc) {
updates.push({ key: 'next_sunrise_utc', value: calc.next_sunrise_utc, LastUpdated: nowIso });
}
